const nodemailer = require('nodemailer');

// Always use mock email service for development
const CLIENT_URL = process.env.CLIENT_URL || 'http://localhost:3000';

console.log('📧 Email service running in DEVELOPMENT MODE - URLs will be logged to console');

const mockTransporter = {
  sendMail: async (mailOptions) => {
    console.log('\n📧 ===== EMAIL VERIFICATION =====');
    console.log('📧 To:', mailOptions.to);
    console.log('📧 Subject:', mailOptions.subject);
    
    // Extract verification URL from email content
    const urlMatch = mailOptions.html?.match(/href="([^"]*)"/);
    if (urlMatch) {
      const verificationUrl = urlMatch[1];
      console.log('🔗 FULL VERIFICATION URL:', verificationUrl);
      console.log('🔗 TOKEN ONLY:', verificationUrl.split('token=')[1]);
      console.log('📝 INSTRUCTIONS: Copy the FULL URL above and open it in your browser to verify email');
      console.log('📧 ===== END EMAIL =====\n');
    }
    
    return { messageId: 'mock-message-id' };
  }
};

const sendVerificationEmail = async (email, verificationToken) => {
  try {
    const verificationUrl = `${CLIENT_URL}/verify-email?token=${verificationToken}`;
    
    const mailOptions = {
      from: `"Career Guidance Platform" <noreply@careerguidance.com>`,
      to: email,
      subject: 'Verify Your Email - Career Guidance Platform',
      html: `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #e0e0e0; border-radius: 8px;">
          <div style="text-align: center; margin-bottom: 20px;">
            <h1 style="color: #1976d2; margin: 0;">Career Guidance Platform</h1>
            <p style="color: #666; margin: 5px 0;">Empowering Education and Employment in Lesotho</p>
          </div>
          
          <h2 style="color: #1976d2;">Welcome to Career Guidance Platform!</h2>
          <p>Thank you for registering. Please verify your email address by clicking the button below:</p>
          
          <div style="text-align: center; margin: 30px 0;">
            <a href="${verificationUrl}" 
               style="background-color: #1976d2; color: white; padding: 12px 30px; 
                      text-decoration: none; border-radius: 4px; display: inline-block;
                      font-size: 16px; font-weight: bold;">
              Verify Email Address
            </a>
          </div>
          
          <p>If the button doesn't work, copy and paste this link in your browser:</p>
          <p style="word-break: break-all; background-color: #f5f5f5; padding: 10px; border-radius: 4px;">
            ${verificationUrl}
          </p>
          
          <p style="color: #666; font-size: 14px;">
            <strong>Note:</strong> This link will expire in 24 hours.
          </p>
          
          <hr style="margin: 30px 0; border: none; border-top: 1px solid #e0e0e0;">
          
          <p style="color: #999; font-size: 12px; text-align: center;">
            If you didn't create an account with Career Guidance Platform, please ignore this email.
          </p>
        </div>
      `,
    };

    const info = await mockTransporter.sendMail(mailOptions);
    console.log('✅ Verification URL generated for:', email);
    return true;
  } catch (error) {
    console.error('❌ Error generating verification URL:', error);
    console.log('🔗 Manual verification token:', verificationToken);
    return false;
  }
};

const sendPasswordResetEmail = async (email, resetToken) => {
  try {
    const resetUrl = `${CLIENT_URL}/reset-password?token=${resetToken}`;
    
    const mailOptions = {
      from: `"Career Guidance Platform" <noreply@careerguidance.com>`,
      to: email,
      subject: 'Reset Your Password - Career Guidance Platform',
      html: `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #e0e0e0; border-radius: 8px;">
          <div style="text-align: center; margin-bottom: 20px;">
            <h1 style="color: #1976d2; margin: 0;">Career Guidance Platform</h1>
            <p style="color: #666; margin: 5px 0;">Password Reset Request</p>
          </div>
          
          <h2 style="color: #1976d2;">Reset Your Password</h2>
          <p>You requested to reset your password. Click the button below to proceed:</p>
          
          <div style="text-align: center; margin: 30px 0;">
            <a href="${resetUrl}" 
               style="background-color: #dc3545; color: white; padding: 12px 30px; 
                      text-decoration: none; border-radius: 4px; display: inline-block;
                      font-size: 16px; font-weight: bold;">
              Reset Password
            </a>
          </div>
          
          <p>If the button doesn't work, copy and paste this link in your browser:</p>
          <p style="word-break: break-all; background-color: #f5f5f5; padding: 10px; border-radius: 4px;">
            ${resetUrl}
          </p>
          
          <p style="color: #666; font-size: 14px;">
            <strong>Note:</strong> This link will expire in 1 hour.
          </p>
          
          <p style="color: #999; font-size: 12px;">
            If you didn't request this password reset, please ignore this email and your password will remain unchanged.
          </p>
        </div>
      `,
    };

    const info = await mockTransporter.sendMail(mailOptions);
    console.log('✅ Password reset URL generated for:', email);
    return true;
  } catch (error) {
    console.error('❌ Error generating password reset URL:', error);
    return false;
  }
};

module.exports = {
  sendVerificationEmail,
  sendPasswordResetEmail,
  transporter: mockTransporter
};
